    @Test void exchangeRefundRecoveryRejectsReceiptOmissionAndRealForeignManifestAcrossEveryStageBeforeNormalResume() throws Exception {
        var scanner=context.getBean(com.example.marketplace.claim.infrastructure.ExchangeRefundRecoveryScanner.class);
        for(String stage:List.of("ITEM_EFFECT","SHIPPING_RESULT","SELLER_REEVALUATE")){
            String suffix=stage.equals("ITEM_EFFECT")?"i":stage.equals("SHIPPING_RESULT")?"s":"r";var pair=new java.util.ArrayList<>(List.of(retainedExchangeRecoveryStage(stage,"e-g"+suffix+"a"),retainedExchangeRecoveryStage(stage,"e-g"+suffix+"b")));pair.sort(java.util.Comparator.comparing(v->v.physical().accepted().exchangeId().toString()));var first=pair.getFirst();var foreign=pair.get(1);UUID id=first.physical().accepted().exchangeId(),other=foreign.physical().accepted().exchangeId();UUID run=scanner.start();UUID scan=jdbc.queryForObject("SELECT first_job_id FROM marketplace.claim_exchange_refund_recovery_stage WHERE run_id=:run AND stage=:stage",Map.of("run",run,"stage",stage),UUID.class);var owned=claimActualExchangeJob(scan,Instant.now());Runnable invoke=()->scanner.scan(owned.job());
            // Planning is a committed stage. Suppress the first candidate receipt and prove its delivery/job/outbox transaction cannot commit.
            jdbc.getJdbcTemplate().execute("CREATE FUNCTION marketplace.e_recovery_missing_candidate() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NULL; END $$");jdbc.getJdbcTemplate().execute("CREATE TRIGGER aaa_e_recovery_missing_candidate BEFORE INSERT ON marketplace.claim_exchange_refund_recovery_candidate FOR EACH ROW EXECUTE FUNCTION marketplace.e_recovery_missing_candidate()");var business=exchangeRefundParticipants();String guard;
            try{var failure=assertThrows(RuntimeException.class,invoke::run);Throwable root=failure;while(root.getCause()!=null){root=root.getCause();}assertTrue(root instanceof java.sql.SQLException,root.toString());assertEquals("23514",((java.sql.SQLException)root).getSQLState());guard=root.getMessage();assertEquals(business,exchangeRefundParticipants());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_recovery_page WHERE run_id=:run AND stage=:stage",Map.of("run",run,"stage",stage),Integer.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_recovery_delivery WHERE run_id=:run AND stage=:stage",Map.of("run",run,"stage",stage),Integer.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_recovery_candidate WHERE run_id=:run AND stage=:stage",Map.of("run",run,"stage",stage),Integer.class));}finally{jdbc.getJdbcTemplate().execute("DROP TRIGGER aaa_e_recovery_missing_candidate ON marketplace.claim_exchange_refund_recovery_candidate");jdbc.getJdbcTemplate().execute("DROP FUNCTION marketplace.e_recovery_missing_candidate()");}
            java.nio.file.Files.writeString(java.nio.file.Path.of(System.getenv("A3_EVIDENCE"),"e-recovery-missing-candidate-"+suffix+".json"),authMapper.writeValueAsString(Map.of("stage",stage,"run",run,"actualSqlState","23514","guard",guard,"durablePlan",1,"candidateDeliveryJobOutboxCommit",0,"businessUnchanged",true)));
            var changes=new java.util.LinkedHashMap<String,String>();changes.put("foreign-order","NEW.order_id='"+foreign.physical().parties().buyer().order().id()+"';");changes.put("foreign-seller","NEW.seller_order_id='"+foreign.physical().parties().shipment().sellerOrderId()+"';");changes.put("foreign-exchange","NEW.exchange_id='"+other+"';");changes.put("foreign-source-fact","NEW.source_fact_id='"+(stage.equals("ITEM_EFFECT")?jdbc.queryForObject("SELECT id FROM marketplace.claim_exchange_refund_consent WHERE exchange_id=:id",Map.of("id",other),UUID.class):other)+"';");changes.put("wrong-type","NEW.type='REFUND_SUBMIT.v1';");changes.put("wrong-cause","NEW.cause_key='"+other+"';");changes.put("wrong-payload","NEW.payload='"+other+"';");changes.put("wrong-fingerprint","NEW.source_fingerprint=repeat('0',64);");changes.put("wrong-run","NEW.run_id='"+scanner.start()+"';");changes.put("wrong-key","NEW.dedupe_key='foreign-exact-recovery-key';");
            if(!stage.equals("SELLER_REEVALUATE")){UUID foreignAttempt=stage.equals("ITEM_EFFECT")?foreign.consent().refundAttemptId():jdbc.queryForObject("SELECT refund_attempt_id FROM marketplace.claim_shipping_obligation WHERE claim_id=:id",Map.of("id",other),UUID.class);var refund=new TransactionTemplate(transactionManager).execute(t->context.getBean(com.example.marketplace.payment.api.Refunds.class).get(foreignAttempt));changes.put("foreign-attempt","NEW.attempt_id='"+foreignAttempt+"';");changes.put("foreign-payment","NEW.payment_id='"+refund.paymentId()+"';");changes.put("wrong-result-version","NEW.result_version=0;");changes.put("wrong-amount","NEW.amount=NEW.amount+1;");changes.put("foreign-reference","NEW.result_reference='"+refund.resultReference()+"';");changes.put("wrong-original-reference","NEW.original_reference='wrong-original-order-fingerprint';");}
            for(var entry:changes.entrySet()){exchangeRecoveryGraphIntervention("claim_exchange_refund_recovery_delivery",suffix+"-"+entry.getKey(),entry.getValue(),false,invoke,id);}exchangeRecoveryGraphIntervention("claim_exchange_refund_recovery_delivery",suffix+"-missing-delivery","",true,invoke,id);exchangeRecoveryGraphIntervention("claim_exchange_refund_recovery_candidate",suffix+"-wrong-owner","NEW.owner_token='"+UUID.randomUUID()+"';",false,invoke,id);exchangeRecoveryGraphIntervention("claim_exchange_refund_recovery_candidate",suffix+"-foreign-exchange","NEW.exchange_id='"+other+"';",false,invoke,id);exchangeRecoveryGraphIntervention("claim_exchange_refund_recovery_candidate",suffix+"-missing-receipt","",true,invoke,id);
            assertEquals(com.example.marketplace.platform.api.JobHandler.Result.COMPLETE,scanner.scan(owned.job()));assertTrue(owned.jobs().complete(scan,owned.job().ownerToken()));scanExchangeRecoveryOnly(run);currentExchangeRefundRecoveryRun=run;drainExchangeRefundRecoveryWork();for(var seed:pair){UUID seller=seed.physical().parties().shipment().sellerOrderId();var rows=jdbc.queryForList("SELECT refund_attempt_id,state FROM marketplace.claim_shipping_obligation WHERE seller_order_id=:id",Map.of("id",seller));assertEquals(1,rows.size());if(!rows.getFirst().get("state").equals("SUCCEEDED")){UUID payment=(UUID)rows.getFirst().get("refund_attempt_id");runCancellationJob("REFUND_SUBMIT.v1",payment);runCancellationJob("REFUND_RESULT_RECORDED.v1",payment);runCancellationJob("SELLER_AFTERCARE_REEVALUATE.v1",seller);}assertEquals("CLOSED",orders().find(seed.physical().parties().buyer().order().orderNumber()).state());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_completion WHERE exchange_id=:id",Map.of("id",seed.physical().accepted().exchangeId()),Integer.class));}java.nio.file.Files.writeString(java.nio.file.Path.of(System.getenv("A3_EVIDENCE"),"e-recovery-exact-graph-resumed-"+suffix+".json"),authMapper.writeValueAsString(Map.of("stage",stage,"run",run,"actualDifferentOrder",foreign.physical().parties().buyer().order().id(),"sqlManifestInterventions",changes.size()+4,"allParticipantRollbacks",true,"normalBothClosed",true)));
        }
    }

    @Test void exchangeRefundRecoveryScanAndDeliveryLoseTheirRealStoredLeaseAfterParentWaitThenOnlyTakeoverCanWrite() throws Exception {
        var seed=retainedExchangeRecoveryStage("ITEM_EFFECT","e-rlease");UUID id=seed.physical().accepted().exchangeId(),order=seed.physical().parties().buyer().order().id();var scanner=context.getBean(com.example.marketplace.claim.infrastructure.ExchangeRefundRecoveryScanner.class);UUID run=scanner.start();UUID scan=jdbc.queryForObject("SELECT first_job_id FROM marketplace.claim_exchange_refund_recovery_stage WHERE run_id=:run AND stage='ITEM_EFFECT'",Map.of("run",run),UUID.class);var clock=new JobClock();clock.now=jdbc.queryForObject("SELECT clock_timestamp()",Map.of(),java.sql.Timestamp.class).toInstant();var old=ownTimedExchangeJob(scan,clock);
        for(boolean delivery:List.of(false,true)){
            UUID jobId=delivery?jdbc.queryForObject("SELECT job_id FROM marketplace.claim_exchange_refund_recovery_delivery WHERE run_id=:run AND stage='ITEM_EFFECT' AND exchange_id=:id",Map.of("run",run,"id",id),UUID.class):scan;var owned=delivery?ownTimedExchangeJob(jobId,clock):old;java.util.concurrent.Callable<com.example.marketplace.platform.api.JobHandler.Result> invoke=()->delivery?exchangeFinancialWith(owned.jobs()).resume(owned.job()):exchangeScannerWith(owned.jobs()).scan(owned.job());
            try(var pool=Executors.newSingleThreadExecutor();var blocker=context.getBean(DataSource.class).getConnection()){blocker.setAutoCommit(false);int pid;try(var q=blocker.createStatement();var r=q.executeQuery("SELECT pg_backend_pid()")){assertTrue(r.next());pid=r.getInt(1);}try(var q=blocker.prepareStatement("SELECT id FROM marketplace.purchase_order WHERE id=? FOR UPDATE")){q.setObject(1,order);q.executeQuery().close();}var future=pool.submit(()->{var lost=assertThrows(IllegalStateException.class,invoke::call);assertEquals("JOB_LEASE_LOST",lost.getMessage());return lost.getMessage();});exchangeRefundAwaitParentChain(pid,1,List.of(future),"e-recovery-final-lease-"+delivery);var before=exchangeRefundParticipants();var metadata=exchangeRecoveryMetadata();var stored=owned.jobs().find(jobId).orElseThrow();assertEquals("RUNNING",stored.status());clock.now=stored.leaseUntil().plusNanos(1000);assertTrue(clock.instant().isAfter(stored.leaseUntil()));blocker.commit();assertEquals("JOB_LEASE_LOST",future.get(10,TimeUnit.SECONDS));assertEquals(before,exchangeRefundParticipants());assertEquals(metadata,exchangeRecoveryMetadata());java.nio.file.Files.writeString(java.nio.file.Path.of(System.getenv("A3_EVIDENCE"),"e-recovery-real-lost-lease-"+delivery+".json"),authMapper.writeValueAsString(Map.of("delivery",delivery,"actualJob",stored,"afterStoredLease",clock.instant(),"actualParentWait",true,"actualFailure","JOB_LEASE_LOST","allBusinessAndRecoveryParticipantsUnchanged",true)));}
            var takeover=ownTimedExchangeJob(jobId,clock);assertNotEquals(owned.job().ownerToken(),takeover.job().ownerToken());var stable=exchangeRefundParticipants();var metadata=exchangeRecoveryMetadata();assertEquals(409,assertThrows(com.example.marketplace.order.api.OrderRejected.class,invoke::call).status());assertEquals(stable,exchangeRefundParticipants());assertEquals(metadata,exchangeRecoveryMetadata());if(delivery){assertEquals(com.example.marketplace.platform.api.JobHandler.Result.COMPLETE,exchangeFinancialWith(takeover.jobs()).resume(takeover.job()));}else{assertEquals(com.example.marketplace.platform.api.JobHandler.Result.COMPLETE,exchangeScannerWith(takeover.jobs()).scan(takeover.job()));}var committed=exchangeRefundParticipants();metadata=exchangeRecoveryMetadata();if(delivery){assertEquals(com.example.marketplace.platform.api.JobHandler.Result.COMPLETE,exchangeFinancialWith(takeover.jobs()).resume(takeover.job()));}else{assertEquals(com.example.marketplace.platform.api.JobHandler.Result.COMPLETE,exchangeScannerWith(takeover.jobs()).scan(takeover.job()));}assertEquals(committed,exchangeRefundParticipants());assertEquals(metadata,exchangeRecoveryMetadata());assertTrue(takeover.jobs().complete(jobId,takeover.job().ownerToken()));
        }
        scanExchangeRecoveryOnly(run);currentExchangeRefundRecoveryRun=run;drainExchangeRefundRecoveryWork();UUID seller=seed.physical().parties().shipment().sellerOrderId(),shipping=jdbc.queryForObject("SELECT refund_attempt_id FROM marketplace.claim_shipping_obligation WHERE seller_order_id=:id",Map.of("id",seller),UUID.class);runCancellationJob("REFUND_SUBMIT.v1",shipping);runCancellationJob("REFUND_RESULT_RECORDED.v1",shipping);runCancellationJob("SELLER_AFTERCARE_REEVALUATE.v1",seller);assertEquals("CLOSED",orders().find(seed.physical().parties().buyer().order().orderNumber()).state());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_effect WHERE exchange_id=:id",Map.of("id",id),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT effects FROM marketplace.payment_refund_mock WHERE attempt_id=:id",Map.of("id",seed.consent().refundAttemptId()),Integer.class));
    }

    @Test void exchangeRefundRecoveryActualChildCandidateCursorAndAckResumeAfterStoredLeaseWithoutDuplicateManifestOrEffect() throws Exception {
        var seed=retainedExchangeRecoveryStage("ITEM_EFFECT","e-rchild");UUID id=seed.physical().accepted().exchangeId();var scanner=context.getBean(com.example.marketplace.claim.infrastructure.ExchangeRefundRecoveryScanner.class);var jobs=context.getBean(com.example.marketplace.platform.api.Jobs.class);var deliveries=new java.util.ArrayList<UUID>();var observations=new java.util.ArrayList<Map<String,Object>>();UUID last=null;
        for(String mode:List.of("RECOVERY_CANDIDATE","RECOVERY_CURSOR","ACK")){
            UUID run=scanner.start();last=run;UUID job=jdbc.queryForObject("SELECT first_job_id FROM marketplace.claim_exchange_refund_recovery_stage WHERE run_id=:run AND stage='ITEM_EFFECT'",Map.of("run",run),UUID.class);var source=jobs.find(job).orElseThrow();Instant at=java.util.stream.Stream.of(Instant.now(),source.nextRunAt().plusNanos(1000),jdbc.queryForObject("SELECT clock_timestamp()",Map.of(),java.sql.Timestamp.class).toInstant()).max(Instant::compareTo).orElseThrow();var folder=java.nio.file.Files.createDirectory(java.nio.file.Path.of(System.getenv("A3_EVIDENCE")).resolve("e-recovery-child-"+mode+"-"+UUID.randomUUID()));Process first=refundProcess(folder,"first",at,job,mode),restart=null;
            try{awaitJobCondition(()->java.nio.file.Files.exists(folder.resolve("first-effect"))||!first.isAlive(),"actual E recovery child must reach the existing probe's "+mode+" marker");assertTrue(java.nio.file.Files.exists(folder.resolve("first-effect")),"actual E recovery child marker not reached; inspect preserved child output");var stored=jobs.find(job).orElseThrow();assertEquals("RUNNING",stored.status());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_recovery_candidate WHERE run_id=:run AND stage='ITEM_EFFECT' AND exchange_id=:id",Map.of("run",run,"id",id),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_recovery_delivery WHERE run_id=:run AND stage='ITEM_EFFECT' AND exchange_id=:id",Map.of("run",run,"id",id),Integer.class));assertEquals(mode.equals("ACK"),jdbc.queryForObject("SELECT completed FROM marketplace.claim_exchange_refund_recovery_stage WHERE run_id=:run AND stage='ITEM_EFFECT'",Map.of("run",run),Boolean.class));var immutable=jdbc.queryForList("SELECT to_jsonb(d)::text FROM marketplace.claim_exchange_refund_recovery_delivery d WHERE run_id=:run ORDER BY id",Map.of("run",run),String.class);var priorClaims=jdbc.queryForList("SELECT to_jsonb(f)::text FROM marketplace.job_claim_fact f ORDER BY job_id,attempt",Map.of(),String.class);var business=exchangeRefundParticipants();business.remove("job");business.remove("job_claim_fact");first.destroyForcibly();assertTrue(ContractTiming.awaitProcess(first,10,TimeUnit.SECONDS));restart=refundProcess(folder,"restart",stored.leaseUntil().plusNanos(1000),job,"NORMAL");assertTrue(ContractTiming.awaitProcess(restart,40,TimeUnit.SECONDS));assertEquals(0,restart.exitValue(),"actual child takeover must replay existing page/candidate evidence");assertEquals("SUCCEEDED",jobs.find(job).orElseThrow().status());assertEquals(2,jobs.find(job).orElseThrow().attempts());assertEquals(immutable,jdbc.queryForList("SELECT to_jsonb(d)::text FROM marketplace.claim_exchange_refund_recovery_delivery d WHERE run_id=:run ORDER BY id",Map.of("run",run),String.class));var allClaims=jdbc.queryForList("SELECT to_jsonb(f)::text FROM marketplace.job_claim_fact f ORDER BY job_id,attempt",Map.of(),String.class);assertTrue(allClaims.containsAll(priorClaims),"every old immutable claim fact survives actual restart");var addedClaims=allClaims.stream().filter(c->!priorClaims.contains(c)).toList();assertEquals(1,addedClaims.size());var claimFact=authMapper.readTree(addedClaims.getFirst());assertEquals(job.toString(),claimFact.get("job_id").asText());assertEquals(stored.attempts()+1,claimFact.get("attempt").asInt());assertEquals(stored.ownerToken().toString(),claimFact.get("previous_owner").asText());assertEquals("TAKEOVER",claimFact.get("eligibility_kind").asText());var newClaim=jdbc.queryForMap("SELECT * FROM marketplace.job_claim_fact WHERE job_id=:id AND attempt=:attempt",Map.of("id",job,"attempt",stored.attempts()+1));assertEquals(stored.leaseUntil(),((java.sql.Timestamp)newClaim.get("required_at")).toInstant());assertEquals(stored.leaseUntil().plusNanos(1000),((java.sql.Timestamp)newClaim.get("claimed_at")).toInstant());assertEquals(stored.leaseUntil().plusNanos(1000).plusSeconds(30),((java.sql.Timestamp)newClaim.get("initial_lease_until")).toInstant());assertEquals(stored.command().nextRunAt(),((java.sql.Timestamp)newClaim.get("scheduled_at_snapshot")).toInstant());assertNotEquals(stored.ownerToken(),newClaim.get("owner_token"));String actualChildClaim=java.nio.file.Files.readString(folder.resolve("restart-effect-claim"));assertTrue(actualChildClaim.contains("id="+job));assertTrue(actualChildClaim.contains("attempts="+(stored.attempts()+1)));assertTrue(actualChildClaim.contains("ownerToken="+newClaim.get("owner_token")));assertTrue(actualChildClaim.contains("leaseUntil="+((java.sql.Timestamp)newClaim.get("initial_lease_until")).toInstant()));var after=exchangeRefundParticipants();after.remove("job");after.remove("job_claim_fact");assertEquals(business,after,"actual scan restart adds no new money/stock/ITEM effects; exact new claim separately proven");assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_recovery_candidate WHERE run_id=:run AND stage='ITEM_EFFECT'",Map.of("run",run),Integer.class));deliveries.addAll(jdbc.queryForList("SELECT job_id FROM marketplace.claim_exchange_refund_recovery_delivery WHERE run_id=:run AND stage='ITEM_EFFECT'",Map.of("run",run),UUID.class));observations.add(Map.of("mode",mode,"run",run,"actualOldJob",stored,"firstExit",first.exitValue(),"restartExit",restart.exitValue(),"restartAfterStoredLease",stored.leaseUntil(),"candidateAndManifestCount",1));}finally{if(first.isAlive()){first.destroyForcibly();ContractTiming.awaitProcess(first,10,TimeUnit.SECONDS);}if(restart!=null&&restart.isAlive()){restart.destroyForcibly();ContractTiming.awaitProcess(restart,10,TimeUnit.SECONDS);}}
        }
        currentExchangeRefundRecoveryRun=last;drainExchangeRefundRecoveryWork();var stable=exchangeRefundRecoveryBusinessState();var beforeReplayClaims=jdbc.queryForList("SELECT to_jsonb(f)::text FROM marketplace.job_claim_fact f ORDER BY job_id,attempt",Map.of(),String.class);var expectedReplayJobs=new java.util.ArrayList<UUID>();for(UUID delivery:deliveries){if(!jobs.find(delivery).orElseThrow().status().equals("SUCCEEDED")){expectedReplayJobs.add(delivery);runExchangeActualJob(delivery);}}assertActualRecoveryClaims(beforeReplayClaims,expectedReplayJobs);assertEquals(stable,exchangeRefundRecoveryBusinessState());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM marketplace.claim_exchange_refund_item_ready WHERE exchange_id=:id",Map.of("id",id),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT submit_calls FROM marketplace.payment_refund_mock WHERE attempt_id=:id",Map.of("id",seed.consent().refundAttemptId()),Integer.class));assertEquals(1,jdbc.queryForObject("SELECT effects FROM marketplace.payment_refund_mock WHERE attempt_id=:id",Map.of("id",seed.consent().refundAttemptId()),Integer.class));java.nio.file.Files.writeString(java.nio.file.Path.of(System.getenv("A3_EVIDENCE"),"e-recovery-actual-child-stages.json"),authMapper.writeValueAsString(observations));
    }
